'use strict';const M=Model,U=OmniUI,$=x=>document.getElementById(x);let value='',epoch=0,busy=false;function clear(){epoch++;value='';$('password').value='';$('save').disabled=true}async function vault(){M.secure(await U.request('vault.capabilities',{}))}$('generate').onclick=()=>{clear();try{value=M.generate(Number($('length').value),$('symbols').value==='yes');$('password').value=value;$('save').disabled=false;U.notify('Generated on this device. Not saved.')}catch(_){U.notify('Secure random generation is unavailable. No password was generated.')}};$('hide').onclick=()=>{clear();U.notify('Generated password cleared.')};$('save').onclick=async()=>{if(!value||busy)return;busy=true;const e=epoch,submitted=value;try{await vault();if(e!==epoch||submitted!==value||!value)return;const r=await U.request('vault.passwords.saveGenerated',{password:submitted});if(e!==epoch||submitted!==value)return;if(r?.saved!==true)throw Error();clear();U.notify('Password saved to the secure vault.')}catch(_){if(e!==epoch||submitted!==value)return;U.notify('Not saved. An unlocked encrypted vault with protected keys is required.')}finally{busy=false}};$('health').onclick=async()=>{if(busy)return;busy=true;const e=epoch;try{await vault();if(e!==epoch)return;const r=M.report(await U.request('vault.passwords.health',{}));if(e!==epoch)return;$('warnings').replaceChildren();for(const x of r.entries.filter(x=>x.weak||x.reused)){const p=document.createElement('p');p.textContent=x.label+' · '+[x.weak?'Weak password':'',x.reused?'Reused password':''].filter(Boolean).join(' · ');$('warnings').append(p)}$('health-summary').textContent=r.checked+' entries checked offline. '+$('warnings').children.length+' need review. Heuristic checks are not a security guarantee.'}catch(_){if(e!==epoch)return;$('health-summary').textContent='Health check unavailable. Unlock an encrypted vault first.'}finally{busy=false}};function clearAll(){clear();$('warnings').replaceChildren();$('health-summary').textContent='Vault health hidden.'}window.addEventListener('blur',clearAll);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearAll()});window.addEventListener('pagehide',clearAll);window.addEventListener('omni-vault-locked',clearAll);clear();U.focus($('generate'));
